const e="5–15 business days",s="20 business days",a="1–2 business days",h=14;const n="help@saltonlinestore.com",o="https://shop.app/m/saltstore",l="Find SALT in Shopify's Shop app. Check out with Shop Pay, pay in installments on eligible orders, and track your delivery in one place.",r=`Orders are processed in ${a} and usually arrive within ${e} of ordering. During holidays or carrier delays, delivery can occasionally take up to ${s}. Every order ships with tracking, and we email the tracking number as soon as it ships. We ship to all 50 US states.`,t=`You can request a return within 14 days of delivery. Items must be unused, in their original packaging, with tags. Email ${n} with your order number to start a return. Some items, such as personal care, custom and sale items, cannot be returned. Damaged or wrong items are always put right.`,i="You can cancel or change an order within 24 hours, before it ships.",c="Pay securely with card, Shop Pay, Apple Pay or Google Pay.",p=[{question:"How long does delivery take?",answer:r},{question:"Is shipping free?",answer:"Yes. Standard shipping is free on all US orders."},{question:"What is the return policy?",answer:t},{question:"Can I cancel my order?",answer:i},{question:"Which payment methods can I use?",answer:c},{question:"Can I buy SALT products in the Shop app?",answer:`Yes. Open ${o} or search "SALT" in the Shop app. You can check out with Shop Pay, pay in installments on eligible orders, and track your delivery there.`}];export{r as D,c as P,t as R,o as S,h as a,e as b,p as c,l as d};
